export interface TextBlock {
  type: 'text'
  text: string
}

export interface ToolUseBlock {
  type: 'tool_use'
  id: string
  name: string
  input: Record<string, unknown>
  /** Ladder (user 2026-09-30, hourglass 明确为排队中): 'pending' = held by the
   *  approval ladder (or still being generated by the stream); 'queued' =
   *  accepted for execution, waiting for a batch-mate / its serial group's
   *  turn; 'running' = its executor has actually entered. Each executor marks
   *  'running' at its own entry (reads/spawn fan out concurrently and mark all
   *  at once). */
  status?: 'pending' | 'queued' | 'approved' | 'running' | 'completed' | 'rejected'
  output?: string
  exitCode?: number | null
  /** spawn_agent only: the sub-conversation this call hosts. Written by the
   *  engine that owns the handle (the main process), so a client learns it from
   *  the tool_status diff — the messages snapshot ships when the assistant
   *  message is created, i.e. before the spawn has a sub-conversation. */
  subConvId?: string
  /** spawn_agent only: the plan node this call implements (spawn_agent planNode=). */
  planNodeId?: string
  /** exec only, background:true (PLAN-coding-contract P0-3): the OS pid the
   *  result settled with. Drives the CommandCard's 后台 tag + kill and routes
   *  killTool through execKill instead of the foreground-process scalar. */
  backgroundPid?: number
}

export interface ToolResultBlock {
  type: 'tool_result'
  tool_use_id: string
  content: string
  is_error?: boolean
  imageData?: string
  /** Pointer to tool_results table (UUID); set when content is stored separately. */
  tool_result_id?: string
  /** Reconcile placeholder marker (llm/tool-reconcile.ts): the block was
   *  fabricated because a request had to go out while the call was still
   *  unanswered. A real result arriving later REPLACES a _synthetic block
   *  (addToolResult) instead of being swallowed by the duplicate guard.
   *  Never serialized to the wire — the adapters map tool_result blocks
   *  field-explicitly. */
  _synthetic?: boolean
}

export interface ThinkingBlock {
  type: 'thinking'
  thinking: string
  signature?: string
}

export interface RedactedThinkingBlock {
  type: 'redacted_thinking'
  data: string
}

export type ContentBlock =
  | TextBlock
  | ToolUseBlock
  | ToolResultBlock
  | ThinkingBlock
  | RedactedThinkingBlock
